public class Main {

    // 题面功能写在外部函数里
    static long[] solve(int n, int[] a, List<Integer>[] graph) {
        int[] tin = new int[n + 1];
        int[] tout = new int[n + 1];
        int[] eulerVal = new int[n + 1];

        int timer = 0;

        // 非递归 DFS
        // state = 0 表示首次到达，state = 1 表示退出节点
        int[] stackU = new int[2 * n + 5];
        int[] stackFa = new int[2 * n + 5];
        int[] stackState = new int[2 * n + 5];
        int top = 0;

        stackU[top] = 1;
        stackFa[top] = 0;
        stackState[top] = 0;
        top++;

        while (top > 0) {
            top--;
            int u = stackU[top];
            int fa = stackFa[top];
            int state = stackState[top];

            if (state == 0) {
                timer++;
                tin[u] = timer;
                eulerVal[timer] = a[u];

                // 退出节点时再处理 tout
                stackU[top] = u;
                stackFa[top] = fa;
                stackState[top] = 1;
                top++;

                // 子节点入栈
                List<Integer> list = graph[u];
                for (int i = 0; i < list.size(); i++) {
                    int v = list.get(i);
                    if (v != fa) {
                        stackU[top] = v;
                        stackFa[top] = u;
                        stackState[top] = 0;
                        top++;
                    }
                }
            } else {
                tout[u] = timer;
            }
        }

        long[] ans = new long[n + 1];
        int B = 20; // 因为 a[i] <= 10^6

        // 按位统计答案
        for (int b = 0; b < B; b++) {
            int[] pre = new int[n + 1];

            // 当前位的前缀和
            for (int i = 1; i <= n; i++) {
                pre[i] = pre[i - 1] + ((eulerVal[i] >> b) & 1);
            }

            long bitValue = 1L << b;

            // 计算每个节点子树在这一位上的贡献
            for (int u = 1; u <= n; u++) {
                int l = tin[u];
                int r = tout[u];
                int ones = pre[r] - pre[l - 1];
                int size = r - l + 1;
                int zeros = size - ones;
                ans[u] += 1L * ones * zeros * bitValue;
            }
        }

        return ans;
    }

