import sys

def solve(n, e, edges):
    # 建图
    graph = [[] for _ in range(n + 1)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # 非递归 DFS 求 tin, tout 与 DFS 序上的能量值
    tin = [0] * (n + 1)
    tout = [0] * (n + 1)
    euler_val = [0] * (n + 1)   # 下标从 1 开始，euler_val[tin[u]] = e[u]

    timer = 0
    stack = [(1, 0, 0)]  # (当前节点, 父节点, 状态: 0=首次进入, 1=即将退出)
    while stack:
        u, fa, state = stack.pop()
        if state == 0:
            timer += 1
            tin[u] = timer
            euler_val[timer] = e[u]
            # 退出时记录 tout
            stack.append((u, fa, 1))
            for v in graph[u]:
                if v != fa:
                    stack.append((v, u, 0))
        else:
            tout[u] = timer

    ans = [0] * (n + 1)
    B = 20  # 因为能量值 <= 10^6 < 2^20

    # 按位统计贡献
    for b in range(B):
        pre = [0] * (n + 1)
        for i in range(1, n + 1):
            pre[i] = pre[i - 1] + ((euler_val[i] >> b) & 1)

        bit_val = 1 << b
        for u in range(1, n + 1):
            l = tin[u]
            r = tout[u]
            ones = pre[r] - pre[l - 1]
            size = r - l + 1
            zeros = size - ones
            ans[u] += ones * zeros * bit_val

    return ans[1:]

def main():
    input_data = sys.stdin.read().strip().split()
    it = iter(input_data)
    n = int(next(it))
    e = [0] + [int(next(it)) for _ in range(n)]
    edges = [(int(next(it)), int(next(it))) for _ in range(n - 1)]
    res = solve(n, e, edges)
    print(' '.join(map(str, res)))

if __name__ == "__main__":
    main()
