                stackState[top] = 1;
                top++;

                // 子节点入栈
                for (int v : graph[u]) {
                    if (v != fa) {
                        stackU[top] = v;
                        stackFa[top] = u;
                        stackState[top] = 0;
                        top++;
                    }
                }
            } else {
                tout[u] = timer;
            }
        }

        long[] ans = new long[n + 1];
        int B = 20; // 能量值 <= 10^6 < 2^20

        for (int b = 0; b < B; b++) {
            int[] pre = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                pre[i] = pre[i - 1] + ((eulerVal[i] >> b) & 1);
            }

            long bitVal = 1L << b;
            for (int u = 1; u <= n; u++) {
                int l = tin[u];
                int r = tout[u];
                int ones = pre[r] - pre[l - 1];
                int size = r - l + 1;
                int zeros = size - ones;
                ans[u] += 1L * ones * zeros * bitVal;
            }
        }

        return ans;
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int[] e = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            e[i] = fs.nextInt();
        }

        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int i = 0; i < n - 1; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            graph[u].add(v);
            graph[v].add(u);
        }

        long[] ans = solve(n, e, graph);
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (i > 1) sb.append(' ');
            sb.append(ans[i]);
        }
        System.out.println(sb);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buf = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            this.in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buf);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buf[ptr++] & 0xff;
        }

        int nextInt() throws IOException {
            int c = read();
            while (c <= ' ') c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
